"""Map parameter type to Python type.

    :param name: parameter name
    :param value: parameter type
    :return: Python type
    """
def _get_param_type(name: str, value: str) -> type {
    t = {"str": str, "int": int}.get(value, None);
    if not t {
        raise Exception(f"unknown type {value} for param {name}");
    }
    return t;
}

test_blocks:
test "t0" {
    assert (_get_param_type("name", "str") == str);;
}

test "t1" {
    assert (_get_param_type("b", "int") == int);;
}

test "t2" {
    assert (_get_param_type(**{"name": "a", "value": "int"}) == int);;
}

test "t3" {
    assert (_get_param_type("name", "int") == int);;
}

test "t4" {
    assert (_get_param_type("foo", "str") == str);;
}

test "t5" {
    assert (_get_param_type("a", "str") == str);;
}

test "t6" {
    assert (_get_param_type("d", "int") == int);;
}

test "t7" {
    assert (_get_param_type("my_param", "int") == int);;
}

test "t8" {
    assert (_get_param_type("c", "str") == str);;
}

test "t9" {
    assert (_get_param_type("a", **{"value": "int"}) == int);;
}
